import AsyncStorage from '@react-native-async-storage/async-storage';
import { Feather, Ionicons } from '@expo/vector-icons';
import React, { useEffect, useMemo, useState } from 'react';
import {
  Modal, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View,
} from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import colors from '@/constants/colors';
import { calculateExpectancy, calculateLotSize, calculateMargin, calculatePricePnL, keepAvailableLessons, parseCompletedLessons } from '@/lib/academyMath';

const c = colors.light;
const PROGRESS_KEY = 'tradiqs.academy.completed-lessons.v1';
type Props = { visible: boolean; onClose: () => void };
type Category = 'All' | 'SMC' | 'Structure' | 'Indicators' | 'Risk';
type Lesson = {
  id: string; title: string; duration: string; overview: string; execution: string[];
  checklist: string[]; invalidation: string; takeaway: string;
};
type Track = { id: string; number: string; title: string; subtitle: string; lessons: Lesson[] };
type Term = { title: string; category: Exclude<Category, 'All'>; definition: string; context: string; identify: string };

const lesson = (id: string, title: string, duration: string, overview: string, execution: string[], checklist: string[], invalidation: string, takeaway: string): Lesson =>
  ({ id, title, duration, overview, execution, checklist, invalidation, takeaway });

const tracks: Track[] = [
  {
    id: 'mechanics', number: '01', title: 'Market Fundamentals & Mechanics', subtitle: 'Build the language of execution.',
    lessons: [
      lesson('candlestick-psychology', 'Candlestick Psychology', '8 MIN', 'Candles record the auction between buyers and sellers. Their location, close, and relationship to prior range are more meaningful than isolated visual patterns.', ['Start with the higher-timeframe range and location.', 'Read close strength relative to the candle range.', 'Use a lower-timeframe candle only as confirmation at a pre-planned zone.'], ['Candle is evaluated in context.', 'Close confirms the intended direction.', 'A structural invalidation is defined.'], 'Ignore a candle signal when it appears in the middle of an unstructured range.', 'A candlestick describes participation; location decides whether it matters.'),
      lesson('orders-sessions', 'Order Types & Trading Sessions', '10 MIN', 'Market, limit, and stop orders solve different execution problems. Session overlap changes liquidity, volatility, and the reliability of a trigger.', ['Use limit orders at pre-planned value zones.', 'Use stop orders only after a defined confirmation level.', 'Match the trade’s expected volatility to London, New York, or overlap conditions.'], ['Order type matches the entry thesis.', 'High-impact events are checked.', 'The active session supports expected range.'], 'Avoid forcing a low-liquidity-session entry simply because price is near a level.', 'An excellent level entered with the wrong order or at the wrong time is still poor execution.'),
      lesson('risk-costs', 'Leverage, Margin & Execution Friction', '7 MIN', 'Leverage changes exposure, not risk tolerance. Margin, slippage, and overnight financing are operating constraints that must fit the trade plan.', ['Set the stop before calculating size.', 'Confirm required margin leaves a safety buffer.', 'Plan for realistic slippage around news and opens.'], ['Stop distance is known.', 'Margin buffer remains after entry.', 'Event risk is acceptable.'], 'Do not enter if a routine price fluctuation could trigger a margin emergency.', 'Leverage magnifies precision and mistakes in equal measure.'),
      lesson('liquidity-providers', 'Liquidity Providers & Market Making', '10 MIN', 'Liquidity providers quote both sides of a market and manage inventory risk. Their presence affects spreads, execution quality, and the reliability of thin-session moves.', ['Check whether the market is in an active liquid session.', 'Compare current spread to its normal range.', 'Use limit orders when execution certainty matters more than immediate fill.'], ['Session has adequate participation.', 'Spread is stable.', 'Order type fits available liquidity.'], 'Avoid treating a thin-market spike as institutional conviction without follow-through.', 'The ease of entering is not proof of the ease of exiting.'),
      lesson('depth-of-market', 'Depth of Market & Order Book Context', '9 MIN', 'Depth of Market shows visible resting interest near price. It is a snapshot, not a guarantee, because orders can be added, cancelled, or hidden.', ['Observe concentration around nearby prices.', 'Compare displayed depth with actual executed response.', 'Use order-book context only alongside price structure.'], ['Visible liquidity aligns with chart location.', 'Price confirms, rather than merely approaches, the level.', 'Risk is based on structure.'], 'Disregard displayed size that disappears repeatedly without executed follow-through.', 'Order-book data is context; price acceptance is confirmation.'),
    ],
  },
  {
    id: 'smc', number: '02', title: 'Smart Money Concepts & Institutional Flow', subtitle: 'Read liquidity and displacement.',
    lessons: [
      lesson('order-blocks', 'Order Blocks & Mitigation', '12 MIN', 'An order block is the final opposing candle before decisive displacement. It is a hypothesis about where unfilled institutional interest may be revisited, not a guaranteed reversal zone.', ['Find impulsive displacement that breaks meaningful structure.', 'Mark the final opposing candle or its relevant range.', 'Wait for a return plus lower-timeframe confirmation.'], ['Displacement is clear.', 'Structure was actually broken.', 'Entry occurs at a defined mitigation zone.'], 'The idea fails when price accepts beyond the origin with no responsive displacement.', 'Trade the reaction and confirmation—not the rectangle itself.'),
      lesson('fvg-liquidity', 'Fair Value Gaps & Liquidity Sweeps', '11 MIN', 'A fair value gap is a three-candle imbalance created by rapid delivery. Liquidity pools often sit above equal highs or below equal lows and can be swept before the intended move.', ['Map obvious external liquidity first.', 'Note imbalances aligned with higher-timeframe bias.', 'Seek entry after a sweep and displacement back through the gap.'], ['External liquidity is visible.', 'FVG aligns with directional context.', 'Sweep has produced a response.'], 'Do not assume every gap fills; invalidate when price continues to accept away from the thesis.', 'Liquidity is a destination; imbalance often describes the route.'),
      lesson('bos-choch', 'BOS, CHoCH & Premium/Discount', '12 MIN', 'Break of Structure confirms continuation in the established direction; Change of Character is an early warning that control may be shifting. Premium and discount frame whether an entry offers favorable relative pricing.', ['Set the dealing range from a meaningful swing.', 'Classify the first opposing structural break as CHoCH.', 'Favor longs in discount and shorts in premium when aligned with bias.'], ['Range is anchored to valid swings.', 'Structure is judged by closes, not wicks alone.', 'Entry location has value.'], 'A structure thesis is invalid when successive closes re-establish the opposing sequence.', 'Direction without location is incomplete; structure and value must agree.'),
      lesson('internal-external-liquidity', 'Internal vs External Liquidity', '10 MIN', 'Internal liquidity is formed by minor swings inside a range; external liquidity sits at its boundaries. Knowing which pool is more consequential stops traders from mistaking a small sweep for the completed objective.', ['Mark the active dealing range.', 'Separate internal pivots from range highs and lows.', 'Wait for a reaction once price reaches the higher-priority pool.'], ['Range boundaries are clear.', 'The intended pool is external or contextually meaningful.', 'Entry waits for displacement.'], 'Do not call a reversal when only internal liquidity has been cleared against a larger external draw.', 'The larger pool usually matters more than the nearest pool.'),
      lesson('inducement-flow', 'Inducement in Institutional Flow', '9 MIN', 'Inducement is a nearby, tempting setup that can collect early orders before price reaches the true objective. It is most useful when paired with a clear external-liquidity target.', ['Identify the obvious minor swing that invites early entries.', 'Locate the larger liquidity target beyond it.', 'Require a decisive response at the intended target before entry.'], ['External objective is marked.', 'Minor level is not confused with invalidation.', 'Stop is beyond the real structural failure point.'], 'Stand aside if price does not react at the external objective or reclaims the inducement level decisively.', 'The obvious setup often provides liquidity for the higher-quality setup.'),
    ],
  },
  {
    id: 'price-action', number: '03', title: 'Advanced Price Action & Market Cycles', subtitle: 'Turn context into confluence.',
    lessons: [
      lesson('wyckoff', 'Wyckoff Schematics & Accumulation', '13 MIN', 'Wyckoff organizes a range into a potential campaign: accumulation before markup or distribution before markdown. The framework is useful only when volume, structure, and subsequent behavior support it.', ['Define the range boundaries and dominant trend.', 'Identify a possible spring or upthrust at range extremes.', 'Require a sign of strength or weakness before committing.'], ['Range has adequate duration.', 'False-break behavior is observable.', 'Follow-through confirms the phase.'], 'Exit the schematic when price cleanly accepts outside the range against the expected campaign.', 'A label is not evidence—follow-through is the evidence.'),
      lesson('power-of-three', 'Power of 3 (AMD)', '10 MIN', 'Accumulation, Manipulation, and Distribution describe a common intraday delivery sequence. The framework is a map for observing behavior, not a prediction that every session must follow.', ['Define the early-session accumulation range.', 'Wait for a sweep beyond one side of that range.', 'Trade only after price confirms distribution toward the opposing objective.'], ['Session range is established.', 'Manipulation has a clear sweep.', 'Distribution has confirmation and room to target.'], 'Discard the setup when price remains accepted inside the accumulation range after the expected window.', 'AMD becomes useful when timing, liquidity, and follow-through agree.'),
      lesson('mtf', 'Multi-Timeframe Confluence', '10 MIN', 'Multi-timeframe analysis assigns a job to each chart: higher timeframes establish location and bias; lower timeframes refine timing and risk.', ['Start with daily or four-hour range and bias.', 'Locate the one-hour decision zone.', 'Use a lower-timeframe shift only as the entry trigger.'], ['Higher-timeframe draw is clear.', 'Entry is located at a higher-timeframe zone.', 'Lower-timeframe trigger protects risk.'], 'Do not keep a lower-timeframe trade when the higher-timeframe premise has failed.', 'Top-down analysis prevents a precise entry from being placed in the wrong market context.'),
      lesson('killzone-timing', 'Killzone Timing & Session Delivery', '8 MIN', 'Killzones are recurring periods of concentrated participation around London and New York. Timing improves selectivity but never overrides the need for a valid location and trigger.', ['Mark session opens and high-impact release times.', 'Build bias before the active window begins.', 'Wait for liquidity sweep and displacement during the planned window.'], ['Time window is active.', 'Bias and location are established.', 'Spread and volatility are normal.'], 'Do not force a trade because a named session window has started without structural confirmation.', 'Time is a filter, not an entry signal.'),
      lesson('volume-profile', 'Volume Profile & Accepted Value', '10 MIN', 'Volume profile organizes participation by price, revealing accepted value and thin auction areas. It helps frame where price may pause, rotate, or accelerate.', ['Mark high-volume nodes and low-volume areas.', 'Compare the current auction with prior accepted value.', 'Use profile levels as confluence with structure and liquidity.'], ['Profile level is visible on the chosen session or composite.', 'Price behavior confirms acceptance or rejection.', 'Target has room before the next high-volume node.'], 'Avoid assuming a node holds when price accepts cleanly through it with displacement.', 'Volume profile tells you where business was done; price tells you whether that value is still defended.'),
    ],
  },
  {
    id: 'risk', number: '04', title: 'Risk Management & Psychology', subtitle: 'Protect capital and decision quality.',
    lessons: [
      lesson('risk-of-ruin', 'Risk-of-Ruin Math', '10 MIN', 'Risk of ruin estimates the chance that a sequence of losses damages the account beyond recovery. It is driven by win rate, payoff ratio, and the percentage risked on every trade.', ['Estimate a conservative win rate and payoff ratio.', 'Set risk low enough to survive a normal losing streak.', 'Review whether the account can absorb the planned drawdown.'], ['Risk per trade is fixed.', 'Losing-streak tolerance is known.', 'Position size follows the risk model.'], 'Do not increase risk after losses to accelerate recovery; this sharply raises ruin risk.', 'Survival is the first return a strategy must earn.'),
      lesson('asymmetric-rr', 'Asymmetric Reward-to-Risk', '9 MIN', 'Asymmetric opportunities risk a defined small amount for a larger plausible reward. The asymmetry must come from market location and realistic liquidity targets, not wishful target placement.', ['Define invalidation first.', 'Target opposing liquidity or a measured range objective.', 'Check that the path to target is not blocked by nearby value.'], ['Stop is structural.', 'Target is realistic.', 'Expected R supports the setup’s historical win rate.'], 'Pass when the target requires price to ignore multiple opposing levels or lacks time to develop.', 'A high R multiple is valuable only when the target has a market reason.'),
      lesson('biases', 'Cognitive Biases & Trade Review', '8 MIN', 'FOMO, revenge trading, recency bias, and confirmation bias turn uncertain outcomes into unstructured risk. A brief review turns results into feedback instead of emotion.', ['Write the thesis before entry.', 'Use an alert rather than chase a missed move.', 'Review process quality independently from P&L.'], ['Entry follows the written plan.', 'Loss limits have not been breached.', 'A post-trade note is captured.'], 'Stop when you notice an urge to change rules solely to recover a prior loss.', 'The best traders protect the process from the last trade’s emotion.'),
      lesson('trade-journaling', 'Trade Journaling & Process Review', '9 MIN', 'A journal converts a trade from a memory into evidence. It captures whether execution followed the plan, allowing recurring strengths and mistakes to become measurable.', ['Save a before-and-after chart image.', 'Record thesis, entry, stop, target, and emotional state.', 'Grade process separately from the outcome.'], ['Plan was documented before entry.', 'Result is tagged by setup type.', 'One improvement is identified without rewriting history.'], 'Do not score a rule-breaking winner as a successful process trade.', 'A journal compounds decision quality when it is honest and consistent.'),
      lesson('drawdown-rules', 'Drawdown Rules & Recovery', '10 MIN', 'Drawdown rules reduce exposure before emotional pressure changes behavior. A recovery plan is a pause-and-review process, not an aggressive attempt to erase losses.', ['Set daily, weekly, and maximum drawdown limits.', 'Reduce size after the first threshold.', 'Pause and review the sample after the final threshold.'], ['Thresholds are written before trading.', 'Current equity is checked.', 'Recovery conditions are objective.'], 'Stop trading immediately once the hard drawdown limit is reached.', 'A controlled pause protects both capital and the quality of the next decision.'),
    ],
  },
  {
    id: 'macro', number: '05', title: 'Macro Fundamentals', subtitle: 'Understand the forces behind repricing.',
    lessons: [
      lesson('central-banks', 'Central Banks & Rate Expectations', '10 MIN', 'Currencies and risk assets reprice around expected policy paths, not only announced rates. The gap between expectations and the statement’s tone often creates the largest move.', ['Check the current rate and market-implied path.', 'Read policy language for changes in bias.', 'Reduce exposure immediately before major decisions unless specifically planned.'], ['Event time is known.', 'Consensus and prior decision are reviewed.', 'Volatility plan is explicit.'], 'Avoid holding a technical setup through a major decision without a defined event-risk strategy.', 'Markets move on the difference between expectation and information.'),
      lesson('cpi-nfp', 'CPI, NFP & High-Impact Data', '9 MIN', 'Inflation and labor data can reset rate expectations in seconds. Initial moves may be thin and volatile; confirmation after the release matters more than prediction.', ['Note forecast, prior, and revision risk.', 'Mark pre-release range liquidity.', 'Wait for spreads and price discovery to normalize before discretionary entry.'], ['Release timestamp is confirmed.', 'Key levels are marked before data.', 'Position size accounts for exceptional volatility.'], 'Cancel entries if post-release price action is disorderly or spreads are abnormal.', 'During data shocks, preservation is a position.'),
      lesson('dxy-correlation', 'DXY Correlation Playbook', '9 MIN', 'The U.S. Dollar Index can provide context for broad dollar strength or weakness. Correlations change, so DXY is a confirmation tool rather than a standalone signal.', ['Identify whether the pair is directly dollar-sensitive.', 'Compare DXY structure with the traded instrument.', 'Use divergence only as context at a valid technical location.'], ['Relationship is relevant to the instrument.', 'Both markets are read on compatible timeframes.', 'Price action still confirms the trade.'], 'Ignore the correlation when DXY and the pair are being driven by different local catalysts.', 'Correlation can sharpen context, but the traded chart owns the execution.'),
      lesson('treasury-yields', 'Treasury Yields & Rate Differentials', '10 MIN', 'Treasury yields express changing expectations for growth, inflation, and policy. Yield differentials can shape currency flows and help explain cross-asset repricing.', ['Track the relevant short- and long-dated yields.', 'Compare yield direction with the currency pair or risk asset.', 'Watch for yield moves around data and central-bank communication.'], ['Yield move is meaningful, not a single tick.', 'Rate narrative matches the broader context.', 'Technical setup remains valid.'], 'Avoid assuming yields dictate an immediate trade when price has not confirmed the relationship.', 'Rates influence the current; price still chooses the entry.'),
      lesson('intermarket-analysis', 'Intermarket Analysis', '11 MIN', 'Intermarket analysis compares currencies, yields, equities, commodities, and volatility to test whether a narrative has broad support. It is especially useful for identifying fragile one-market moves.', ['Choose two or three relevant related markets.', 'Look for confirmation or divergence around key levels.', 'Use the cross-asset view to adjust conviction, not remove risk controls.'], ['Related markets support the thesis.', 'A technical trigger exists on the traded asset.', 'Event risk is known across the complex.'], 'Stand aside when cross-asset signals conflict and the primary chart has no clear edge.', 'The strongest narratives leave evidence across more than one market.'),
    ],
  },
];
const availableLessonIds = new Set(tracks.flatMap((track) => track.lessons.map((item) => item.id)));

const dictionary: Term[] = [
  { title: 'Order Block (OB)', category: 'SMC', definition: 'The final opposing candle before strong displacement that breaks meaningful structure.', context: 'Institutions may revisit this origin to mitigate remaining orders.', identify: 'Find a decisive move that breaks structure; mark the final opposing candle before it.' },
  { title: 'Fair Value Gap (FVG)', category: 'SMC', definition: 'A three-candle price imbalance created by rapid delivery.', context: 'It can reveal inefficient auctioning and a potential rebalancing area.', identify: 'Compare candle one and three wicks; the untouched space between them is the gap.' },
  { title: 'Liquidity Pool', category: 'SMC', definition: 'A visible cluster of resting stops or pending orders near obvious levels.', context: 'Large participants need available orders to transact efficiently.', identify: 'Mark equal highs, equal lows, prior day extremes, and range boundaries.' },
  { title: 'Buy-Side Liquidity', category: 'SMC', definition: 'Stops and breakout orders resting above highs.', context: 'Price may seek this inventory before repricing lower or continuing higher.', identify: 'Look above equal highs, swing highs, and prior session highs.' },
  { title: 'Sell-Side Liquidity', category: 'SMC', definition: 'Stops and breakdown orders resting below lows.', context: 'Price may seek this inventory before repricing higher or continuing lower.', identify: 'Look below equal lows, swing lows, and prior session lows.' },
  { title: 'Mitigation Block', category: 'SMC', definition: 'A previously defended zone revisited to rebalance or close exposure.', context: 'It is useful only when paired with structure and displacement.', identify: 'Locate a failed swing or origin that led to a meaningful reaction.' },
  { title: 'Inducement', category: 'SMC', definition: 'A tempting internal level that draws early entries before a larger liquidity objective.', context: 'It helps explain why obvious setups can be swept first.', identify: 'Compare minor internal swings against the more obvious external range target.' },
  { title: 'Break of Structure (BOS)', category: 'Structure', definition: 'A decisive continuation break through a prior swing in the trend direction.', context: 'It supports the current directional auction when paired with displacement.', identify: 'Use meaningful swing points and favor candle closes over isolated wicks.' },
  { title: 'Change of Character (CHoCH)', category: 'Structure', definition: 'The first notable break against the prevailing swing sequence.', context: 'It can signal that control is beginning to transfer, not that reversal is guaranteed.', identify: 'After a trend, mark the first break through its protected opposing swing.' },
  { title: 'Premium vs Discount', category: 'Structure', definition: 'Relative pricing above or below the midpoint of a defined dealing range.', context: 'It frames whether a long or short is being considered at favorable value.', identify: 'Draw the range from valid swing low to high and mark the 50% equilibrium.' },
  { title: 'Wyckoff Spring', category: 'Structure', definition: 'A brief break below range support that returns into the range.', context: 'It can expose failed selling pressure before accumulation progresses.', identify: 'Require a range, a downside probe, quick recovery, and later confirmation.' },
  { title: 'Average True Range (ATR)', category: 'Indicators', definition: 'A volatility measure based on the average true range over a chosen lookback.', context: 'ATR helps normalize stop and target distance to current conditions.', identify: 'Apply ATR and compare current reading with recent session ranges.' },
  { title: 'Exponential Moving Average (EMA)', category: 'Indicators', definition: 'A moving average that weights recent prices more heavily.', context: 'It can provide a dynamic trend reference, not a standalone entry signal.', identify: 'Use slope and price relationship across a meaningful timeframe.' },
  { title: 'Relative Strength Index (RSI)', category: 'Indicators', definition: 'A momentum oscillator that compares recent gains and losses.', context: 'Divergence or regime behavior can support context; overbought is not an automatic sell.', identify: 'Compare RSI swings with price swings and broader market structure.' },
  { title: 'Volume Profile', category: 'Indicators', definition: 'A distribution of traded volume across prices.', context: 'High-volume nodes can reflect accepted value; low-volume areas may move quickly.', identify: 'Inspect session or composite profile for nodes and thin zones.' },
  { title: 'Risk-Reward Ratio (RRR)', category: 'Risk', definition: 'The planned reward divided by the amount risked to the stop.', context: 'It must be considered with realistic win rate and target probability.', identify: 'Divide entry-to-target distance by entry-to-invalidation distance.' },
  { title: 'Drawdown', category: 'Risk', definition: 'The decline from an account’s peak equity to a later low.', context: 'It measures the capital and psychological pressure a strategy must survive.', identify: 'Track equity peak-to-trough, not only individual trade losses.' },
  { title: 'Margin Call', category: 'Risk', definition: 'A broker action when account equity no longer supports required margin.', context: 'It is a leverage-control failure, not a normal stop-loss mechanism.', identify: 'Monitor free margin and stressed position exposure before entry.' },
  { title: 'Pip', category: 'Risk', definition: 'A standard unit of price movement used to quantify currency-pair changes.', context: 'Pip value links chart distance to monetary risk.', identify: 'Confirm the instrument’s decimal convention before calculating position size.' },
  { title: 'Spread', category: 'Risk', definition: 'The difference between the bid and ask price.', context: 'Spread is an immediate execution cost and can widen during illiquid or news periods.', identify: 'Compare live bid and ask against the planned stop distance.' },
  { title: 'Stop Loss', category: 'Risk', definition: 'A predefined exit that proves the trade thesis wrong.', context: 'It should sit beyond market invalidation, then determine position size.', identify: 'Place it beyond the structural level that invalidates the setup.' },
  { title: 'Position Size', category: 'Risk', definition: 'The quantity traded after risk, stop distance, and pip value are known.', context: 'Size is the adjustable variable that keeps a setup inside account rules.', identify: 'Calculate it from fixed account risk rather than confidence.' },
];

const categories: Category[] = ['All', 'SMC', 'Structure', 'Indicators', 'Risk'];
const Field = ({ label, value, onChange, suffix }: { label: string; value: string; onChange: (value: string) => void; suffix?: string }) => (
  <View style={styles.field}><Text style={styles.fieldLabel}>{label}</Text><View style={styles.inputRow}><TextInput value={value} onChangeText={onChange} keyboardType="decimal-pad" placeholder="0" placeholderTextColor={c.mutedForeground} style={styles.input} />{suffix && <Text style={styles.suffix}>{suffix}</Text>}</View></View>
);
const usd = (value: number) => Number.isFinite(value) ? `$${value.toFixed(2)}` : '—';

export function AcademyModal({ visible, onClose }: Props) {
  const insets = useSafeAreaInsets();
  const [expandedTrack, setExpandedTrack] = useState('mechanics');
  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(null);
  const [completed, setCompleted] = useState<string[]>([]);
  const [hydrated, setHydrated] = useState(false);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState<Category>('All');
  const [expandedTerm, setExpandedTerm] = useState<string | null>(null);
  const [tool, setTool] = useState<'lot' | 'rr' | 'pnl' | 'margin' | null>(null);
  const [inputs, setInputs] = useState<Record<string, string>>({ balance: '10000', risk: '1', stop: '25', winRate: '45', reward: '2', entry: '1.1000', target: '1.1050', loss: '1.0980', lots: '0.10', tradeSize: '100000', leverage: '50' });

  useEffect(() => {
    AsyncStorage.getItem(PROGRESS_KEY).then((raw) => {
      const parsed = parseCompletedLessons(raw);
      const current = keepAvailableLessons(parsed, availableLessonIds);
      setCompleted(current);
      if (current.length !== parsed.length) AsyncStorage.setItem(PROGRESS_KEY, JSON.stringify(current)).catch(() => {});
    }).catch(() => {}).finally(() => setHydrated(true));
  }, []);

  const allLessons = useMemo(() => tracks.flatMap((track) => track.lessons), []);
  const progress = Math.round((completed.length / allLessons.length) * 100);
  const filteredTerms = useMemo(() => dictionary.filter((term) => {
    const query = search.trim().toLowerCase();
    return (category === 'All' || term.category === category) && (!query || `${term.title} ${term.definition} ${term.context}`.toLowerCase().includes(query));
  }), [category, search]);
  const updateInput = (key: string) => (value: string) => setInputs((current) => ({ ...current, [key]: value }));
  const markComplete = () => {
    if (!selectedLesson || completed.includes(selectedLesson.id)) return;
    const next = [...completed, selectedLesson.id];
    setCompleted(next);
    AsyncStorage.setItem(PROGRESS_KEY, JSON.stringify(next)).catch(() => {});
  };
  const number = (key: string) => Number(inputs[key]);
  const balance = number('balance'); const risk = number('risk'); const stop = number('stop');
  const lotCalculation = calculateLotSize(balance, risk, stop);
  const expectancy = calculateExpectancy(number('winRate'), number('reward'));
  const pnl = calculatePricePnL(number('entry'), number('target'), number('loss'), number('lots'));
  const margin = calculateMargin(number('tradeSize'), number('leverage'));

  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <SafeAreaView edges={['bottom']} style={styles.safe}>
        <View style={[styles.header, { paddingTop: Math.max(insets.top, 14) }]}><TouchableOpacity accessibilityRole="button" accessibilityLabel="Go back" onPress={onClose} style={styles.backButton}><Ionicons name="arrow-back" size={22} color={c.foreground} /></TouchableOpacity><View style={styles.headerCopy}><Text style={styles.eyebrow}>TRADIQS ACADEMY</Text><Text style={styles.title}>Build your institutional edge.</Text></View></View>
        <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
          <View style={styles.hero}><View><Text style={styles.heroLabel}>BOOTCAMP PROGRESS</Text><Text style={styles.heroTitle}>{hydrated ? `${completed.length}/${allLessons.length}` : '—'} lessons complete</Text></View><Text style={styles.progressValue}>{hydrated ? `${progress}%` : '...'}</Text><View style={styles.progressTrack}><View style={[styles.progressFill, { width: `${hydrated ? progress : 0}%` }]} /></View><Text style={styles.heroHint}>Progress is saved privately on this device.</Text></View>
          <View style={styles.mindset}><Feather name="shield" size={17} color={c.accent} /><View style={styles.mindsetCopy}><Text style={styles.mindsetLabel}>PROFESSIONAL MINDSET</Text><Text style={styles.quote}>“Amateurs focus on how much they can make. Professionals focus on how much they can lose.”</Text></View></View>
          <Text style={styles.section}>FIVE-TRACK CURRICULUM</Text>
          {tracks.map((track) => {
            const open = expandedTrack === track.id; const done = track.lessons.filter((item) => completed.includes(item.id)).length;
            return <View key={track.id} style={styles.track}>
              <TouchableOpacity style={styles.trackHeader} activeOpacity={0.8} onPress={() => setExpandedTrack(open ? '' : track.id)}><View style={styles.trackNumber}><Text style={styles.trackNumberText}>{track.number}</Text></View><View style={styles.trackCopy}><Text style={styles.trackTitle}>{track.title}</Text><Text style={styles.trackSubtitle}>{track.subtitle} · {done}/{track.lessons.length}</Text></View><Feather name={open ? 'chevron-up' : 'chevron-down'} size={19} color={c.accent} /></TouchableOpacity>
              {open && <View style={styles.lessons}>{track.lessons.map((item, index) => { const doneLesson = completed.includes(item.id); return <TouchableOpacity key={item.id} style={styles.lessonRow} onPress={() => setSelectedLesson(item)}><View style={[styles.lessonStatus, doneLesson && styles.lessonStatusDone]}>{doneLesson ? <Feather name="check" size={13} color={c.background} /> : <Text style={styles.lessonIndex}>{String(index + 1).padStart(2, '0')}</Text>}</View><View style={styles.lessonCopy}><Text style={styles.lessonTitle}>{item.title}</Text><Text style={styles.lessonMeta}>{item.duration} · READER</Text></View><Feather name="arrow-up-right" size={16} color={c.mutedForeground} /></TouchableOpacity>; })}</View>}
            </View>;
          })}
          <Text style={styles.section}>TRADING DICTIONARY</Text>
          <View style={styles.searchRow}><Feather name="search" size={17} color={c.mutedForeground} /><TextInput value={search} onChangeText={setSearch} placeholder="Search definitions, concepts..." placeholderTextColor={c.mutedForeground} style={styles.search} /></View>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.filters}>{categories.map((item) => <TouchableOpacity key={item} onPress={() => setCategory(item)} style={[styles.filter, category === item && styles.filterActive]}><Text style={[styles.filterText, category === item && styles.filterTextActive]}>{item}</Text></TouchableOpacity>)}</ScrollView>
          <Text style={styles.resultsLabel}>{filteredTerms.length} TERMS</Text>
          {filteredTerms.map((term) => { const open = expandedTerm === term.title; return <View key={term.title} style={styles.termCard}><TouchableOpacity style={styles.termHeader} onPress={() => setExpandedTerm(open ? null : term.title)}><View style={styles.termCopy}><Text style={styles.termTitle}>{term.title}</Text><Text style={styles.termDefinition} numberOfLines={open ? undefined : 2}>{term.definition}</Text></View><Feather name={open ? 'minus' : 'plus'} size={18} color={c.accent} /></TouchableOpacity>{open && <View style={styles.termDetail}><Text style={styles.detailLabel}>INSTITUTIONAL CONTEXT</Text><Text style={styles.detailText}>{term.context}</Text><Text style={styles.detailLabel}>HOW TO IDENTIFY ON CHARTS</Text><Text style={styles.detailText}>{term.identify}</Text></View>}</View>; })}
          {!filteredTerms.length && <Text style={styles.empty}>No dictionary terms match this search.</Text>}
          <Text style={styles.section}>TRADER&apos;S TOOLKIT</Text>
          <View style={styles.toolGrid}>
            <TouchableOpacity style={styles.toolCard} onPress={() => setTool('lot')}><View style={styles.toolIcon}><Feather name="pie-chart" size={20} color={c.accent} /></View><Text style={styles.toolTitle}>Lot Size Calculator</Text><Text style={styles.toolDescription}>Size a position from fixed account risk.</Text><Text style={styles.toolAction}>OPEN TOOL  ›</Text></TouchableOpacity>
            <TouchableOpacity style={styles.toolCard} onPress={() => setTool('rr')}><View style={styles.toolIcon}><Feather name="trending-up" size={20} color={c.accent} /></View><Text style={styles.toolTitle}>Risk/Reward Simulator</Text><Text style={styles.toolDescription}>Model expectancy from win rate and R:R.</Text><Text style={styles.toolAction}>OPEN TOOL  ›</Text></TouchableOpacity>
            <TouchableOpacity style={styles.toolCard} onPress={() => setTool('pnl')}><View style={styles.toolIcon}><Feather name="activity" size={20} color={c.accent} /></View><Text style={styles.toolTitle}>P/L Simulator</Text><Text style={styles.toolDescription}>Model price-based profit and loss.</Text><Text style={styles.toolAction}>OPEN TOOL  ›</Text></TouchableOpacity>
            <TouchableOpacity style={styles.toolCard} onPress={() => setTool('margin')}><View style={styles.toolIcon}><Feather name="layers" size={20} color={c.accent} /></View><Text style={styles.toolTitle}>Margin Calculator</Text><Text style={styles.toolDescription}>Estimate capital required for exposure.</Text><Text style={styles.toolAction}>OPEN TOOL  ›</Text></TouchableOpacity>
          </View>
        </ScrollView>
      </SafeAreaView>
      <Modal visible={Boolean(selectedLesson)} animationType="slide" onRequestClose={() => setSelectedLesson(null)}>
        <SafeAreaView style={styles.safe}><View style={styles.readerHeader}><TouchableOpacity onPress={() => setSelectedLesson(null)} style={styles.back}><Feather name="chevron-left" size={23} color={c.foreground} /><Text style={styles.backText}>ACADEMY</Text></TouchableOpacity><Text style={styles.readerMeta}>{selectedLesson?.duration}</Text></View>
          {selectedLesson && <ScrollView contentContainerStyle={styles.readerContent} showsVerticalScrollIndicator={false}><Text style={styles.eyebrow}>INSTITUTIONAL LESSON</Text><Text style={styles.readerTitle}>{selectedLesson.title}</Text><Text style={styles.overview}>{selectedLesson.overview}</Text><Text style={styles.readerSection}>STEP-BY-STEP EXECUTION RULES</Text>{selectedLesson.execution.map((rule, index) => <View key={rule} style={styles.rule}><Text style={styles.ruleNumber}>{index + 1}</Text><Text style={styles.ruleText}>{rule}</Text></View>)}<Text style={styles.readerSection}>TRADE CHECKLIST</Text>{selectedLesson.checklist.map((item) => <View key={item} style={styles.check}><Feather name="check-circle" size={16} color={c.success} /><Text style={styles.checkText}>{item}</Text></View>)}<View style={styles.invalidation}><Feather name="alert-triangle" size={18} color="#FF9A9A" /><View style={styles.invalidationCopy}><Text style={styles.invalidationTitle}>INVALIDATION CONDITION</Text><Text style={styles.invalidationText}>{selectedLesson.invalidation}</Text></View></View><View style={styles.takeaway}><Text style={styles.takeawayLabel}>PRO TIP · KEY TAKEAWAY</Text><Text style={styles.takeawayText}>{selectedLesson.takeaway}</Text></View><TouchableOpacity style={[styles.completeButton, completed.includes(selectedLesson.id) && styles.completedButton]} onPress={markComplete}><Feather name={completed.includes(selectedLesson.id) ? 'check-circle' : 'award'} size={18} color={c.background} /><Text style={styles.completeText}>{completed.includes(selectedLesson.id) ? 'LESSON COMPLETED' : 'MARK AS COMPLETED'}</Text></TouchableOpacity></ScrollView>}
        </SafeAreaView>
      </Modal>
      <Modal visible={Boolean(tool)} animationType="slide" onRequestClose={() => setTool(null)}>
        <SafeAreaView style={styles.safe}><View style={styles.readerHeader}><TouchableOpacity onPress={() => setTool(null)} style={styles.back}><Feather name="chevron-left" size={23} color={c.foreground} /><Text style={styles.backText}>ACADEMY</Text></TouchableOpacity></View><ScrollView contentContainerStyle={styles.toolModal}><Text style={styles.eyebrow}>TRADER&apos;S TOOLKIT</Text><Text style={styles.readerTitle}>{tool === 'lot' ? 'Lot Size Calculator' : tool === 'rr' ? 'Risk/Reward Simulator' : tool === 'pnl' ? 'P/L Simulator' : 'Margin Calculator'}</Text>{tool === 'lot' ? <><Text style={styles.toolIntro}>For major FX pairs using an estimated $10 pip value per standard lot. Always verify your broker’s instrument specification.</Text><Field label="Account balance" value={inputs.balance} onChange={updateInput('balance')} suffix="USD" /><Field label="Risk per trade" value={inputs.risk} onChange={updateInput('risk')} suffix="%" /><Field label="Stop loss distance" value={inputs.stop} onChange={updateInput('stop')} suffix="PIPS" /><View style={styles.calculation}><Text style={styles.calculationLabel}>RISK AMOUNT</Text><Text style={styles.calculationValue}>{lotCalculation ? usd(lotCalculation.riskAmount) : 'Enter valid inputs'}</Text><Text style={styles.calculationLabel}>ESTIMATED POSITION SIZE</Text><Text style={styles.calculationValue}>{lotCalculation ? `${lotCalculation.lots.toFixed(2)} lots` : '—'}</Text><Text style={styles.assumption}>Formula: risk amount ÷ (stop loss pips × $10 pip value)</Text></View></> : tool === 'rr' ? <><Text style={styles.toolIntro}>Estimate the expected R-multiple per trade using your historical win rate and planned reward-to-risk ratio.</Text><Field label="Win rate" value={inputs.winRate} onChange={updateInput('winRate')} suffix="%" /><Field label="Reward-to-risk ratio" value={inputs.reward} onChange={updateInput('reward')} suffix="R" /><View style={styles.calculation}><Text style={styles.calculationLabel}>EXPECTANCY PER TRADE</Text><Text style={styles.calculationValue}>{expectancy !== null ? `${expectancy >= 0 ? '+' : ''}${expectancy.toFixed(2)}R` : 'Enter valid inputs'}</Text><Text style={styles.calculationLabel}>EXPECTED RESULT OVER 20 TRADES</Text><Text style={styles.calculationValue}>{expectancy !== null ? `${expectancy >= 0 ? '+' : ''}${(expectancy * 20).toFixed(2)}R` : '—'}</Text><Text style={styles.assumption}>Formula: (win rate × reward) − (loss rate × 1R)</Text></View></> : tool === 'pnl' ? <><Text style={styles.toolIntro}>Estimate profit, loss, and reward-to-risk from exact price levels and your planned lot size.</Text><Field label="Entry price" value={inputs.entry} onChange={updateInput('entry')} /><Field label="Take profit price" value={inputs.target} onChange={updateInput('target')} /><Field label="Stop loss price" value={inputs.loss} onChange={updateInput('loss')} /><Field label="Lot size" value={inputs.lots} onChange={updateInput('lots')} suffix="LOTS" /><View style={styles.calculation}><Text style={styles.calculationLabel}>ESTIMATED PROFIT</Text><Text style={styles.calculationValue}>{pnl ? usd(pnl.profit) : 'Enter valid inputs'}</Text><Text style={styles.calculationLabel}>ESTIMATED LOSS · R:R</Text><Text style={styles.calculationValue}>{pnl ? `${usd(pnl.loss)} · ${pnl.rewardRisk?.toFixed(2) ?? '—'}R` : '—'}</Text><Text style={styles.assumption}>Assumes 100,000 units per standard FX lot; excludes spread, fees, and slippage.</Text></View></> : <><Text style={styles.toolIntro}>Estimate the margin required for a planned position. Keep sufficient free margin for normal market movement.</Text><Field label="Trade size" value={inputs.tradeSize} onChange={updateInput('tradeSize')} suffix="USD" /><Field label="Leverage" value={inputs.leverage} onChange={updateInput('leverage')} suffix=":1" /><View style={styles.calculation}><Text style={styles.calculationLabel}>ESTIMATED REQUIRED MARGIN</Text><Text style={styles.calculationValue}>{margin !== null ? usd(margin) : 'Enter valid inputs'}</Text><Text style={styles.assumption}>Formula: trade size ÷ leverage. Your broker may use different requirements.</Text></View></>}</ScrollView></SafeAreaView>
      </Modal>
    </Modal>
  );
}

